// Keeps only changes to the tools in 'Your settings' that this workflow has not posted before.
const s = $('Your settings').first().json;
const want = String(s.tools || '').split(',').map(t => t.trim().toLowerCase()).filter(Boolean);
const store = $getWorkflowStaticData('global');
const seen = new Set(store.seen || []);
const firstRun = !store.started;
const since = new Date(Date.now() - Number(s.first_run_days || 7) * 86400000).toISOString().slice(0, 10);
const all = $input.first().json.items || [];
const fresh = all.filter(c => !seen.has(c.id)
  && (want.length === 0 || want.includes(c.tool) || want.includes(String(c.tool_name).toLowerCase()))
  && (!firstRun || c.date >= since));
for (const c of all) seen.add(c.id);
store.seen = Array.from(seen).slice(-1000);
store.started = true;
return fresh.reverse().map(c => {
  const link = c.our_page.replace('utm_source=ail_feed', 'utm_source=n8n').replace('utm_medium=json', 'utm_medium=template_slack');
  return { json: { ...c, text: `*${c.tool_name}* changed (${c.date}): ${c.summary}\nMore: ${link}\nSource: AI Leakage (aileakage.com), CC BY 4.0` } };
});
